using System;using System.IO;using System.Linq;using System.Reflection;using System.Text;using UnityEngine;using UnityEditor;using UnityEngine.SceneManagement;
[InitializeOnLoad]public static class BeachShapeAudit{static BeachShapeAudit(){EditorApplication.update+=Poll;}static void Poll(){if(EditorApplication.isCompiling||!File.Exists("BeachShapeAudit.request"))return;File.Delete("BeachShapeAudit.request");var scene=SceneManager.GetSceneByPath("Assets/Editor/DayNightBackups/Gangstar Final Env.unity");var root=scene.GetRootGameObjects().Single(g=>g.name=="Track Roads");var f=root.GetComponentsInChildren<MeshFilter>().Single(v=>v.name=="Outer_MEsh");var data=typeof(FinalPNGCityDetails).GetMethod("Read",BindingFlags.Static|BindingFlags.NonPublic).Invoke(null,new object[]{f.sharedMesh});var p=((Vector3[])data.GetType().GetField("p").GetValue(data)).Select(f.transform.TransformPoint).ToArray();File.WriteAllLines("FinalEnvironmentRoadReview/BeachWorldVertices.csv",p.Select(v=>v.x.ToString("R",System.Globalization.CultureInfo.InvariantCulture)+","+v.y.ToString("R",System.Globalization.CultureInfo.InvariantCulture)+","+v.z.ToString("R",System.Globalization.CultureInfo.InvariantCulture)));File.WriteAllText("FinalEnvironmentRoadReview/BeachAudit.txt","shore vertices="+p.Length+" bounds="+f.GetComponent<Renderer>().bounds);}}
